window.NVS_AI_open=function(context){previous=document.activeElement;overlay.classList.add('is-open');overlay.setAttribute('aria-hidden','false');const label=typeof context==='string'?context:(context&&context.module)||'Nghiệp vụ chung';contextSelect.value=Array.from(contextSelect.options).some(x=>x.value===label)?label:'Nghiệp vụ chung';let user={};try{user=JSON.parse(NVS_localStore.getItem('user')||NVS_sessionStore.getItem('user')||'{}')}catch(_){}identity.textContent=[user.hoTen||'',user.chucVu||user.viTriViecLam||'',user.toBoPhan||''].filter(Boolean).join(' · ');window.NVS_AI_V4_init(user,label);question.focus()};
